"""Splitting type of p in Q(zeta_ell)^+ from the residue p mod ell (full pinning)."""
from __future__ import annotations

from typing import Dict


def factorize(n: int) -> Dict[int, int]:
    out: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


def splitting_type(p: int, ell: int) -> int:
    """Residue degree f(p) = ord(p^2 mod ell), computed by stripping prime factors from m.

    Since ord(p^2) divides m = (ell-1)/2, start from f = m and divide out each prime q
    as long as (p^2)^(f/q) is still 1.  Cost: O(omega(m) * log m) modular exponentiations.
    """
    if ell % 2 == 0 or p % ell == 0:
        raise ValueError("need an odd prime ell not dividing p")
    m = (ell - 1) // 2
    r = p * p % ell
    f = m
    for q, e in factorize(m).items():
        for _ in range(e):
            if pow(r, f // q, ell) == 1:
                f //= q
            else:
                break
    return f


if __name__ == "__main__":
    for p in [2, 3, 7, 8, 37, 191, 1000003]:
        print(p, "->", splitting_type(p, 19))

"""Factor-degree pattern of a squarefree integer polynomial over GF(p) by distinct-degree
factorisation.  For the minimal polynomial of 2cos(2pi/19) the pattern is [f^(9/f)]."""
from __future__ import annotations

from typing import List

Poly = List[int]  # coefficients, lowest degree first


def trim(a: Poly) -> Poly:
    while a and a[-1] == 0:
        a.pop()
    return a


def pmod(a: Poly, b: Poly, p: int) -> Poly:
    a = trim([c % p for c in a]); b = trim([c % p for c in b])
    inv = pow(b[-1], p - 2, p)
    while len(a) >= len(b):
        c = a[-1] * inv % p; s = len(a) - len(b)
        for i, x in enumerate(b):
            a[s + i] = (a[s + i] - c * x) % p
        trim(a)
    return a


def pmul(a: Poly, b: Poly, p: int) -> Poly:
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            out[i + j] = (out[i + j] + x * y) % p
    return trim(out)


def pgcd(a: Poly, b: Poly, p: int) -> Poly:
    a = trim([c % p for c in a]); b = trim([c % p for c in b])
    while b:
        a, b = b, pmod(a, b, p)
    inv = pow(a[-1], p - 2, p)
    return [c * inv % p for c in a]


def pdiv(a: Poly, b: Poly, p: int) -> Poly:
    a = trim([c % p for c in a]); inv = pow(b[-1], p - 2, p)
    q = [0] * (len(a) - len(b) + 1)
    while len(a) >= len(b) and a:
        c = a[-1] * inv % p; s = len(a) - len(b); q[s] = c
        for i, x in enumerate(b):
            a[s + i] = (a[s + i] - c * x) % p
        trim(a)
    return trim(q)


def powmod(base: Poly, e: int, mod: Poly, p: int) -> Poly:
    r: Poly = [1]; base = pmod(base, mod, p)
    while e:
        if e & 1:
            r = pmod(pmul(r, base, p), mod, p)
        base = pmod(pmul(base, base, p), mod, p); e >>= 1
    return r


def factor_pattern(f: Poly, p: int) -> List[int]:
    f = trim([c % p for c in f]); pattern: List[int] = []; k = 0; xp: Poly = [0, 1]
    while len(f) > 1:
        k += 1
        if 2 * k > len(f) - 1:
            pattern.append(len(f) - 1); break
        xp = powmod(xp, p, f, p)
        diff = trim([(xp[i] if i < len(xp) else 0) - (1 if i == 1 else 0) for i in range(max(len(xp), 2))])
        g = pgcd(f, diff, p)
        if len(g) > 1:
            pattern += [k] * ((len(g) - 1) // k)
            f = pdiv(f, g, p); xp = pmod(xp, f, p)
    return sorted(pattern)


PSI19: Poly = [1, 5, -10, -20, 15, 21, -7, -8, 1, 1]  # x^9 + x^8 - 8x^7 - ... + 5x + 1

if __name__ == "__main__":
    for p in [2, 3, 7, 11, 37, 101, 191]:
        pat = factor_pattern(PSI19, p)
        print(f"p = {p:4d}: pattern {pat}, roots in GF(p): {pat.count(1)}")

"""Exact mutual information by enumeration, applied to the semiprime readouts at degree nine:
the which-factor extra (exactly 0) and the split-count law."""
from __future__ import annotations

import math
from collections import Counter
from typing import Hashable, Sequence


def H(values: Sequence[Hashable]) -> float:
    n = len(values)
    return -sum(c / n * math.log2(c / n) for c in Counter(values).values())


def MI(xs: Sequence[Hashable], ys: Sequence[Hashable]) -> float:
    return H(xs) + H(ys) - H(list(zip(xs, ys)))


def eta(x: float) -> float:
    return 0.0 if x <= 0 else -x * math.log2(x)


def or_dial(n: int) -> float:
    h = lambda x: eta(x) + eta(1 - x)
    return h((2 * n - 1) / n**2) - h(1 / n) / n - (n - 1) / n * h(2 / n)


def split_count_law(n: int) -> float:
    return or_dial(n) + eta(1 / n**2) + eta(2 * (n - 1) / n**2) - eta((2 * n - 1) / n**2)


def ftype(u: int, ell: int = 19) -> int:
    r, k, x = u * u % ell, 1, u * u % ell
    while x != 1:
        x = x * r % ell; k += 1
    return k


if __name__ == "__main__":
    ell = 19
    pairs = [(u, v) for u in range(1, ell) for v in range(1, ell)]
    N = [u * v % ell for u, v in pairs]
    ordered = [(ftype(u), ftype(v)) for u, v in pairs]
    unordered = [tuple(sorted(t)) for t in ordered]
    print("I(N; unordered pair) =", round(MI(N, unordered), 5))
    print("which-factor extra   =", MI(N, ordered) - MI(N, unordered))
    S = [int(ftype(u) == 1) + int(ftype(v) == 1) for u, v in pairs]
    print("I(N; split count)    =", round(MI(N, S), 5), " law:", round(split_count_law(9), 5))
    print("OR-dial I_s(9)       =", round(or_dial(9), 5))

