"""The fixed-root dichotomy across the abelian ladder.

For each degree m = 1..40, plot the splitting-type entropy H_phi(m) (what the residue,
or the factor pattern, reveals) against the entropy of the root-count readout
H(1/m, 1 - 1/m).  The two bars coincide exactly when m is 1 or prime.
"""
from __future__ import annotations

import math
from typing import List

import matplotlib.pyplot as plt


def totient(n: int) -> int:
    return sum(1 for k in range(1, n + 1) if math.gcd(k, n) == 1)


def eta(x: float) -> float:
    return 0.0 if x <= 0 else -x * math.log2(x)


def totient_entropy(m: int) -> float:
    return sum(eta(totient(d) / m) for d in range(1, m + 1) if m % d == 0)


def is_prime(n: int) -> bool:
    return n >= 2 and all(n % k for k in range(2, int(math.isqrt(n)) + 1))


def main() -> None:
    ms: List[int] = list(range(1, 41))
    h_type = [totient_entropy(m) for m in ms]
    h_root = [eta(1 / m) + eta(1 - 1 / m) for m in ms]
    fig, ax = plt.subplots(figsize=(12, 5))
    ax.bar([m - 0.2 for m in ms], h_type, width=0.4, color="#4c72b0", label="type entropy $H_\\varphi(m)$")
    ax.bar([m + 0.2 for m in ms], h_root, width=0.4, color="#dd8452", label="root-count entropy $H(1/m,1-1/m)$")
    for m, a, b in zip(ms, h_type, h_root):
        if m == 1 or is_prime(m):
            ax.annotate("=", (m, max(a, b) + 0.05), ha="center", color="green", fontsize=12)
    ax.axvline(9, color="gray", ls=":", lw=1)
    ax.text(9.4, 2.3, "degree nine:\n1.2244 vs 0.5033 bits", ha="left", fontsize=9)
    ax.set_xlabel("degree $m$ of the cyclic field")
    ax.set_ylabel("bits")
    ax.set_title("Counting roots is lossless exactly on prime degrees (green '=')")
    ax.legend()
    plt.tight_layout()
    plt.savefig("fixed_root_dichotomy.png", dpi=150)
    plt.show()


if __name__ == "__main__":
    main()
